void require(bool okay,const char* message){if(!okay)throw std::runtime_error(message);}
void rawSourceColumnCleanup(){
 QTemporaryDir files;const auto fixture=QFileInfo(QString::fromUtf8(__FILE__)).dir().absoluteFilePath("../tests/fixtures/biff/financial-source.xls"),path=files.filePath("Otis-10-K-Raw.xls");require(QFile::copy(fixture,path),"copy the actual untouched 120-sheet raw source");MainWindow window;window.show();QApplication::processEvents();require(window.openWorkbook(path),"open the actual BIFF source for native cleanup");auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());window.findChild<QTabBar*>("workspace.sheets")->setCurrentIndex(32);require(model->sheetId()=="sheet-33","traverse to the raw operations statement tab");
 const auto select=[&](int first,int last){grid->setCurrentIndex(model->index(0,first));grid->selectionModel()->select(QItemSelection(model->index(0,first),model->index(model->rowCount()-1,last)),QItemSelectionModel::ClearAndSelect);grid->setFocus();};select(6,12);require(window.executeCommand("cells.unmerge"),"unmerge source columns before their native moves");const auto g16=model->raw(15,6),m16=model->raw(15,12);require(!g16.isEmpty()&&!m16.isEmpty(),"actual source has the expected two financial-year values");
 const auto move=[&](int source,int destination){select(source,source);QTest::keyClick(grid,Qt::Key_X,Qt::ControlModifier);select(destination,destination);QTest::keyClick(grid,Qt::Key_V,Qt::ControlModifier);};const auto before=window.currentSession().snapshot();move(6,10);require(model->raw(15,10)==g16&&model->raw(15,6).isEmpty(),"actual source full-column G-to-K keyboard move retains financial data");require(window.executeCommand("undo")&&window.currentSession().snapshotView().at("sheets")==before.at("sheets")&&window.executeCommand("redo"),"actual 120-sheet source move is exactly one undoable transaction");move(12,8);require(model->raw(15,8)==m16&&model->raw(15,12).isEmpty(),"actual source full-column M-to-I keyboard move retains financial data");select(6,7);require(window.executeCommand("columns.delete"),"delete original G:H through the structural command");require(model->raw(15,6)==m16&&model->raw(15,8)==g16,"the moved source years shift together after deleting G:H");require(window.saveWorkbook(path)&&window.windowFilePath()==path&&!window.isWindowModified(),"save the actual cleaned source directly under its original .xls filename");const auto reopened=readWorkbook(path.toStdString()).workbook;require(reopened.at("sheets").size()==120,"native cleanup save retains every original source sheet");bool found=false;for(const auto& cell:reopened.at("sheets")[32].at("cells"))if(cell.at("row")==16&&cell.at("col")==9){found=true;require(cell.at("input")==g16.toStdString(),"reopened original-name BIFF source retains the moved financial value");}require(found,"saved source retains the final year cell");
}
void wholeColumnNativeClipboard(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());require(model->setData(model->index(15,6),"12112",Qt::EditRole)&&model->setData(model->index(16,12),"3500",Qt::EditRole),"seed source cleanup columns G and M");const auto original=window.currentSession().snapshot();
 const auto selectColumn=[&](int column){grid->setCurrentIndex(model->index(0,column));grid->selectionModel()->clearSelection();grid->selectColumn(column);grid->setFocus();require(grid->selectionModel()->selection().size()==1&&grid->selectionModel()->selection().front().left()==column,"fixture selects exactly the requested whole column");};selectColumn(6);QTest::keyClick(grid,Qt::Key_X,Qt::ControlModifier);require(QApplication::clipboard()->mimeData()->hasFormat("application/x-tigersheets-cells+json")&&window.currentSession().snapshot()==original,"real Ctrl+X captures a complete column without mutating source");selectColumn(10);QTest::keyClick(grid,Qt::Key_V,Qt::ControlModifier);require(model->raw(15,10)=="12112"&&model->raw(15,6).isEmpty(),"real Ctrl+V moves G into whole column K");require(window.executeCommand("undo")&&window.currentSession().snapshotView().at("sheets")==original.at("sheets"),"one Undo restores the entire source-column move");selectColumn(12);QTest::keyClick(grid,Qt::Key_X,Qt::ControlModifier);selectColumn(8);QTest::keyClick(grid,Qt::Key_V,Qt::ControlModifier);require(model->raw(16,8)=="3500"&&model->raw(16,12).isEmpty(),"the second source cleanup cut moves whole M into I");
 selectColumn(8);QTest::keyClick(grid,Qt::Key_C,Qt::ControlModifier);require(QApplication::clipboard()->text().contains("3500"),"sparse clipboard exposes bounded used-cell TSV alongside its full native range");bool warned=false;QTimer::singleShot(0,&window,[&]{if(auto* dialog=qobject_cast<QMessageBox*>(QApplication::activeModalWidget())){warned=true;dialog->button(QMessageBox::Cancel)->click();}});selectColumn(9);QTest::keyClick(grid,Qt::Key_V,Qt::ControlModifier);require(!warned&&model->raw(16,9)=="3500"&&model->raw(16,8)=="3500","copying and pasting equal whole columns preserves true clipboard dimensions without a size warning");
 selectColumn(8);auto* viewport=grid->horizontalHeader()->viewport();const QPoint point(grid->horizontalHeader()->sectionViewportPosition(8)+10,8);QContextMenuEvent context(QContextMenuEvent::Mouse,point,viewport->mapToGlobal(point));QApplication::sendEvent(viewport,&context);QApplication::processEvents();auto* menu=window.findChild<QMenu*>("worksheet.contextMenu");require(menu&&menu->findChild<QAction*>("context.copy")->isEnabled()&&menu->findChild<QAction*>("context.cut")->isEnabled(),"whole-column context menu exposes Copy and Cut");menu->close();
}
void clipboardOwnershipConflict(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());require(model->setData(model->index(1,1),"7",Qt::EditRole),"seed a local clipboard failure source");grid->setCurrentIndex(model->index(1,1));const auto before=window.currentSession().snapshot();auto* clipboard=QApplication::clipboard();bool replacing=false;const auto conflict=QObject::connect(clipboard,&QClipboard::dataChanged,&window,[&]{if(!replacing&&clipboard->mimeData()->hasFormat("application/x-tigersheets-cells+json")){replacing=true;clipboard->setText("Another application's content");replacing=false;}});bool warned=false;QTimer::singleShot(0,&window,[&]{if(auto* box=qobject_cast<QMessageBox*>(QApplication::activeModalWidget())){warned=box->icon()==QMessageBox::Warning&&box->standardButtons()==QMessageBox::Ok&&box->text().startsWith("We could not copy the content to the Clipboard, it is in use by another application. You can still paste your content within this workbook but it will not");box->button(QMessageBox::Ok)->click();}});require(window.executeCommand("copy"),"a failed system clipboard publication retains a local copy");QObject::disconnect(conflict);require(warned&&clipboard->text()=="Another application's content"&&window.currentSession().snapshot()==before,"clipboard ownership conflict displays the observed warning without overwriting the other application or editing cells");auto* border=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");require(border&&border->isVisible(),"clipboard conflict retains the copied source outline");grid->setCurrentIndex(model->index(3,3));require(window.executeCommand("paste")&&model->raw(3,3)=="7"&&window.executeCommand("undo")&&window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"the retained local clipboard pastes inside its workbook in one undoable edit");clipboard->setText("New external content");grid->setCurrentIndex(model->index(4,3));require(window.executeCommand("paste")&&model->raw(4,3)=="New external content","a later external clipboard replacement cancels the retained fallback");
}
void pasteSizeWarning(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());for(int row=0;row<3;++row)require(model->setData(model->index(row+30,0),QString("Label %1").arg(row+1),Qt::EditRole),"seed scratch label column");grid->setCurrentIndex(model->index(30,0));grid->selectionModel()->select(QItemSelection(model->index(30,0),model->index(32,0)),QItemSelectionModel::ClearAndSelect);require(window.executeCommand("copy"),"copy scratch labels");grid->setCurrentIndex(model->index(33,0));grid->selectionModel()->clearSelection();grid->selectRow(33);const auto before=window.currentSession().snapshot();bool warned=false;QTimer::singleShot(0,&window,[&]{if(auto* dialog=qobject_cast<QMessageBox*>(QApplication::activeModalWidget())){warned=dialog->text()=="The data you’re pasting isn’t the same size as your selection. Do you want to paste anyway?"&&dialog->standardButtons()==(QMessageBox::Ok|QMessageBox::Cancel)&&dialog->defaultButton()==dialog->button(QMessageBox::Ok);dialog->button(QMessageBox::Cancel)->click();}});require(!window.executeCommand("paste")&&warned,"pasting a label column into a selected whole row displays OK/Cancel size warning");require(window.currentSession().snapshot()==before&&grid->selectionModel()->selection().front().width()==model->columnCount(),"Cancel retains the selected row and workbook history");auto* outline=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");require(outline&&outline->isVisible(),"Cancel retains the copied label column outline");grid->setCurrentIndex(model->index(33,1));require(window.executeCommand("paste")&&model->raw(33,1)=="Label 1"&&model->raw(35,1)=="Label 3","selecting only B34 then pasting accepts the entire column");grid->setCurrentIndex(model->index(39,1));grid->selectionModel()->select(QItemSelection(model->index(39,1),model->index(40,2)),QItemSelectionModel::ClearAndSelect);bool accepted=false;QTimer::singleShot(0,&window,[&]{if(auto* dialog=qobject_cast<QMessageBox*>(QApplication::activeModalWidget())){accepted=true;dialog->button(QMessageBox::Ok)->click();}});require(window.executeCommand("paste")&&accepted&&model->raw(39,1)=="Label 1"&&model->raw(41,1)=="Label 3"&&model->raw(39,2).isEmpty(),"OK pastes the original source rectangle at the selection's top-left");require(window.executeCommand("undo")&&model->raw(39,1).isEmpty()&&model->raw(41,1).isEmpty(),"accepting mismatch produces one undoable edit");
}
void copySourceAnimates(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());require(model->setData(model->index(1,1),"12",Qt::EditRole),"seed copy source");const auto first=model->index(1,1),last=model->index(2,2);grid->setCurrentIndex(first);grid->selectionModel()->select(QItemSelection(first,last),QItemSelectionModel::ClearAndSelect);const auto before=window.currentSession().snapshot();
 require(window.executeCommand("copy"),"copy a rectangular selection");QApplication::processEvents();auto* border=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");require(border&&border->isVisible(),"Copy must display a source-range border");require(border->property("sourceRect").toRect()==grid->visualRect(first).united(grid->visualRect(last)).adjusted(1,1,-1,-1),"copy border surrounds the complete source rectangle");auto* animation=border->findChild<QVariantAnimation*>("worksheet.copyAnimation");require(animation&&animation->state()==QAbstractAnimation::Running,"copy border must animate automatically");const auto phase=border->property("dashOffset").toReal();animation->setCurrentTime(150);require(border->property("dashOffset").toReal()!=phase,"advancing the animation moves the painted dash offset");grid->setCurrentIndex(model->index(5,4));require(border->property("sourceRect").toRect()==grid->visualRect(first).united(grid->visualRect(last)).adjusted(1,1,-1,-1),"navigation leaves marching dashes on the copied cells");require(window.currentSession().snapshot()==before,"copy animation and navigation never mutate the workbook or history");
}
void copyCancellation(bool replacement){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());require(model->setData(model->index(0,0),"23",Qt::EditRole)&&window.executeCommand("copy"),"copy before cancellation");auto* border=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");auto* animation=border->findChild<QVariantAnimation*>("worksheet.copyAnimation");const auto before=window.currentSession().snapshot();if(replacement)QApplication::clipboard()->setText("copied from another application");else{grid->setFocus();QKeyEvent escape(QEvent::KeyPress,Qt::Key_Escape,Qt::NoModifier);QApplication::sendEvent(grid,&escape);}require(!border->isVisible()&&animation->state()==QAbstractAnimation::Stopped,replacement?"replacing the clipboard cancels the old copy animation":"Escape cancels the copy animation");require(window.currentSession().snapshot()==before,"copy cancellation leaves values and history untouched");
}
void repeatedPasteAndSheetSwitch(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());auto* tabs=window.findChild<QTabBar*>("workspace.sheets");require(window.executeCommand("sheet.add"),"create another worksheet before copying");tabs->setCurrentIndex(0);grid->setCurrentIndex(model->index(0,0));require(model->setData(model->index(0,0),"23",Qt::EditRole)&&window.executeCommand("copy"),"copy before repeated pastes");auto* border=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");auto* animation=border->findChild<QVariantAnimation*>("worksheet.copyAnimation");const auto source=border->property("sourceRect").toRect();
 for(const int row:{2,4}){grid->setCurrentIndex(model->index(row,0));require(window.executeCommand("paste")&&model->raw(row,0)=="23","copy supports repeated paste");require(border->isVisible()&&border->property("sourceRect").toRect()==source&&animation->state()==QAbstractAnimation::Running,"repeated paste retains the animated source border");}const auto before=window.currentSession().snapshot();window.recalculateNow();require(border->isVisible()&&window.currentSession().snapshot()==before,"calculation refresh preserves copy mode and history");tabs->setCurrentIndex(1);require(!border->isVisible()&&animation->state()!=QAbstractAnimation::Running,"copy animation hides and pauses on other worksheets");tabs->setCurrentIndex(0);require(border->isVisible()&&animation->state()==QAbstractAnimation::Running&&border->property("sourceRect").toRect()==source,"returning to the source sheet restores its animated border");
}
void workbookAndEditCancellation(bool reopen){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());require(model->setData(model->index(0,0),"23",Qt::EditRole),"seed copy before workbook change");QTemporaryDir files;const auto path=files.filePath("copied.xlsx");if(reopen)require(window.saveWorkbook(path),"save source workbook before copying");require(window.executeCommand("copy"),"copy before workbook or editing action");auto* border=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");auto* animation=border->findChild<QVariantAnimation*>("worksheet.copyAnimation");if(reopen)require(window.openWorkbook(path),"reopen a workbook with the same sheet identifiers");else require(window.executeCommand("cells.format",{{"style",{{"bold",true}}}}),"formatting makes a real revision change");require(!border->isVisible()&&animation->state()==QAbstractAnimation::Stopped,reopen?"opening a workbook cancels the previous copy mode":"a workbook editing action cancels the source animation");
}
void frozenCopyOutline(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());const auto first=model->index(0,0),last=model->index(2,1);grid->setCurrentIndex(first);grid->selectionModel()->select(QItemSelection(first,last),QItemSelectionModel::ClearAndSelect);require(window.executeCommand("copy")&&window.executeCommand("view.freeze"),"copy a range crossing the frozen top row");QApplication::processEvents();auto* frozen=window.findChild<QTableView*>("worksheet.frozen");require(frozen,"frozen worksheet exists");auto* frozenBorder=frozen->viewport()->findChild<QWidget*>("worksheet.copyBorder");require(frozenBorder&&frozenBorder->isVisible(),"frozen top row shows the copied range's animated border");auto* bodyBorder=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");require(bodyBorder->property("sourceRect").toRect().top()<0,"the scrolling body must not invent a top border below the frozen row");frozen->setFocus();QKeyEvent escape(QEvent::KeyPress,Qt::Key_Escape,Qt::NoModifier);QApplication::sendEvent(frozen,&escape);require(!frozenBorder->isVisible()&&!bodyBorder->isVisible(),"Escape in the frozen worksheet cancels both copy outlines");require(window.executeCommand("copy"),"copy again before editing a frozen-row cell");const auto before=window.currentSession().snapshot();frozen->setCurrentIndex(model->index(0,0));QTest::keyClick(frozen,Qt::Key_F2);require(!frozenBorder->isVisible()&&!bodyBorder->isVisible()&&window.currentSession().snapshot()==before,"starting a frozen-row edit cancels both outlines without a workbook mutation");
}
void scrollingCopyOutline(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());const auto first=model->index(1,1),last=model->index(2,2);grid->setCurrentIndex(first);grid->selectionModel()->select(QItemSelection(first,last),QItemSelectionModel::ClearAndSelect);require(window.executeCommand("copy"),"copy before scrolling");auto* border=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");auto* animation=border->findChild<QVariantAnimation*>("worksheet.copyAnimation");grid->horizontalScrollBar()->setValue(170);grid->verticalScrollBar()->setValue(40);const auto source=border->property("sourceRect").toRect();require(source.left()<0&&source.top()<0&&source==grid->visualRect(first).united(grid->visualRect(last)).adjusted(1,1,-1,-1),"partially scrolled copy retains true offscreen edges instead of fabricating viewport edges");require(border->geometry()==grid->viewport()->rect(),"copy overlay stays attached to the viewport while scrolling");grid->verticalScrollBar()->setValue(200);require(!border->isVisible()&&animation->state()==QAbstractAnimation::Paused,"fully offscreen copy pauses its animation");grid->horizontalScrollBar()->setValue(0);grid->verticalScrollBar()->setValue(0);window.resize(window.width()+120,window.height()+40);QApplication::processEvents();require(border->isVisible()&&animation->state()==QAbstractAnimation::Running&&border->geometry()==grid->viewport()->rect(),"scrolling back and resizing restore the correctly sized copy overlay");const auto before=window.currentSession().snapshot();grid->setFocus();QTest::keyClick(grid,Qt::Key_F2);require(!border->isVisible()&&animation->state()==QAbstractAnimation::Stopped&&window.currentSession().snapshot()==before,"starting a cell edit cancels copy animation without committing a change");
}
void cutLifecycle(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());
 require(model->setData(model->index(0,0),"10",Qt::EditRole)&&model->setData(model->index(0,1),"=A1*2",Qt::EditRole),"clipboard UI setup");grid->setCurrentIndex(model->index(0,1));const auto before=window.currentSession().snapshot();
 require(window.executeCommand("cut")&&window.currentSession().snapshot()==before,"native Cut command defers mutation");auto* border=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");require(border&&border->isVisible(),"Cut displays the animated source border too");grid->setFocus();QKeyEvent escape(QEvent::KeyPress,Qt::Key_Escape,Qt::NoModifier);QApplication::sendEvent(grid,&escape);
 require(QApplication::clipboard()->text().isEmpty(),"Escape on the worksheet cancels and clears the pending cut clipboard");require(window.currentSession().snapshot()==before,"cancelling Cut leaves source and undo history untouched");
 require(!border->isVisible(),"Escape clears the cut outline");require(window.executeCommand("cut"),"cut again after cancel");grid->setCurrentIndex(model->index(1,1));require(!window.executeCommand("paste.special",{{"mode","values"}})&&border->isVisible()&&window.currentSession().snapshot()==before,"failed cut Paste Special retains the source animation and data");require(window.executeCommand("paste"),"native Paste moves cut source");require(model->raw(0,1).isEmpty()&&model->raw(1,1)=="=A1*2","native Cut/Paste uses move reference semantics");require(QApplication::clipboard()->text().isEmpty()&&!border->isVisible(),"successful move consumes the cut clipboard and animation");require(window.executeCommand("undo")&&window.currentSession().snapshot().at("sheets")==before.at("sheets"),"native move undo restores the whole source/destination change");
}
int main(int argc,char**argv){QApplication app(argc,argv);QTemporaryDir state;qputenv("TIGERSHEETS_STATE_DIR",state.path().toUtf8());try{const auto selected=argc>1?std::string(argv[1]):std::string();if(selected.empty()||selected=="clipboard_conflict")clipboardOwnershipConflict();if(selected.empty()||selected=="size_warning")pasteSizeWarning();if(selected.empty()||selected=="copy_animation")copySourceAnimates();if(selected.empty()||selected=="copy_escape")copyCancellation(false);if(selected.empty()||selected=="clipboard_replace")copyCancellation(true);if(selected.empty()||selected=="repeat_paste")repeatedPasteAndSheetSwitch();if(selected.empty()||selected=="copy_edit")workbookAndEditCancellation(false);if(selected.empty()||selected=="copy_reopen")workbookAndEditCancellation(true);if(selected.empty()||selected=="frozen_copy")frozenCopyOutline();if(selected.empty()||selected=="copy_scroll")scrollingCopyOutline();if(selected.empty()||selected=="cut")cutLifecycle();if(selected.empty()||selected=="whole_column")wholeColumnNativeClipboard();if(selected.empty()||selected=="raw_cleanup")rawSourceColumnCleanup();std::cout<<"worksheet clipboard UI passed\n";
 }catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
